INSERT INTO `Profile` (`id`, `user_id`, `bio`, `balance`, `meta`, `avatar`) VALUES
  ('s8cu5zpkgmklys1eulr05fry', '01969fb5-5314-77e9-80bb-3368923fe2b2', 'かせぎ せんげん 掛ける もはん げいひんかん 金縛り れいせい しゅいん 薬. こせき そうぐう 牛乳 たれる 瞬く ふくし あつかい ひがい 漂う. 早々 怒鳴る えんちょうする 下さい よくし 出版 ぎょうし 重い 憂い 栄誉.', '2124.75', '{"note":"こはん 揺さぶる しょくん かんさい 錠 がいよう そんざい.","tags":["総括","なさけない","比較"],"score":49}', X'1ba51035bab66ca39ef58c3df6a2bfb4'),
  ('emcwjxyrf3bzwohpxz0aplrl', '019b1e9e-492e-74ad-b135-d23edfb2db73', '平安 なかよし ねんがん 日没. かんえん ねんがじょう 浮世絵 勝手. 愛する 手作り しきもう 川底 解説.', '1005.74', '{"note":"主観的 はきだす 乾燥 シアトルし ひんきゃく 日刊 かいぞく つくる ゆれる 詰め込む.","tags":["むこう","いく"],"score":74}', X'b4ccf4411aaa67df2bc0d67fa1e0ddd0'),
  ('eh3rl2mf26hirm86dwjv1862', '0196ceee-f087-7321-90a4-1419f5e43440', NULL, '3163.79', '{"note":"馬 鋭い ふたたび.","tags":["親切","のうみん"],"score":20}', X'3ebb9cecf19a9fb6d9cec4dc87fec7f0'),
  ('furdr37sltoi16u3umrmgw8f', '0194ae34-8559-7124-91fe-b5611049e836', 'だいどころ 遮断 きょうどう. こわす 秘める 対応 くら 一文字 はなのあな 重い ぐん 歯. 聴者 せんげん しゅうり.', '4406.05', NULL, X'dcde551d6f0bb0efffea8fa5f69fb60c'),
  ('fq4omxdn6w751yekxfvtscgn', '0197a080-c19d-7790-a945-6cea95eedd60', 'いちにち ちょうせん こうつう ふん せん かんじる 子守歌 こづつみ. 揺さぶる 漬物 こわす こい. 桜色 甲乙 既に.', '4988.38', '{"note":"ししょく こくひん ほうき.","tags":["ことばつき"],"score":57}', X'f78dd9f3cdcf1cfcc3cbd3d5a0248d0c'),
  ('lpht0tjlm3zjx8ef4wtjwfbn', '0194ccb5-e684-7178-8878-dbf07801ff0c', 'かわさき せいめい 緊張する 慶弔 かいそく 店 警官. 自宅 宝くじ つぎ. 錠 あらあらしい あらしお.', '367.61', '{"note":"じきしょうそう 出かける 報じる.","tags":["家具","しょうりゃく"],"score":68}', X'bebcb2bbbe90f6e17d263dbebf5f1d40'),
  ('knx2nkf9ny74rgq1noyfeqwq', '01954ca3-013f-7258-a999-6d4601784673', 'ひふ あらじお 順序 あさねぼう 約 帳簿. 初めに 芽 入江 こっせつ 入江 六 てのこう. なつかしい たいりく 漠然 凝固 ふきつ ようい たいこうする ふねんゴミ 勇気.', '317.97', '{"note":"けいじばん きひん 憶測 しえんする いさぎよい きずつく よわよわしい ふきつ.","tags":["ふくし","提案する","察知"],"score":46}', NULL),
  ('xakxmh4oeeumby3gayxw04o4', '019ae940-d16b-75a6-83ec-73db395991cd', '化粧 たいほう 非難 検査 ぼくし 同音異義語 早々. 終点 山葵 たて 構える かど. かざる 〜亭 窓 川底 ふかのう 貫く 曲 めいわくめーる はなぢ 雑費.', '2976.85', '{"note":"受付 いしずえ しんじゅく 失う 血液 ろくおん 妥協する いつ頃.","tags":["たくす"],"score":59}', NULL),
  ('ojp7c9qr88hhogvype0etuhx', '0196268a-b3f5-768e-a053-1b221c4b63e9', 'かいじゅう がくふ 好奇心 よくし 指定する. れいてん 先週 継承 じこ 休日 とめる 奉仕 博物館. 拒否 じこ がいよう.', '1242.95', NULL, X'f8e35b32e7f46dc2921c24129369423e'),
  ('t3ti014rxddfudr5rxq73p5d', '01980a06-d5d5-734e-af4c-6e3b734680ec', '没頭 錠 あつかい 山葵 縛る けいじばん. 日刊 ために 原因 ついたち きいろ きぼうする 競艇 ふじょ 移譲. 以下 ひとごみ 程 魔術 哀れむ ちゅうとはんぱ 知り合い 味噌 帝 がくふ.', '3584.31', '{"note":"舞踏 慶弔 ねんじゅう きいろ 救急車 沖縄 手作り.","tags":["ろくおん","たいこうする"],"score":19}', X'ef213e9dcfb6bde8ab856a5aeea945dd'),
  ('i0p877x8ao839lkezgp0bfnk', '0198bcd2-dc43-70f0-8a85-95bfecb3e948', NULL, '1561.63', '{"note":"知り合い 渦巻き のうみん さいほう 氏名 まんえつ 病床 桜色 愛国心 せっとく.","tags":["検査","提案する","ずいぶん"],"score":32}', NULL),
  ('uanln6zxtkna012yk80pk612', '01942c8d-6b5e-7712-80ea-a139932bc8db', 'せんじょう 安泰 あおい こいぬ 壊す. 不思議 りゃくご せいめい たい 忍者 もちいる つみ. 希望する たまご 墨 書架 瞬く いなか 敬語 母.', '458.06', '{"note":"唄う 察知 しょうじょう 既に さわやか 話 りゅうこうご こうとう 近視 すいがら.","tags":["ひんかく","開閉"],"score":42}', NULL),
  ('klnqjzjb1hhychhgjimoaewt', '019661e5-75cc-74c2-a9a9-cacb8575c7e3', NULL, '3630.95', '{"note":"頑張れ いっぱく つうこん 飽くまでも.","tags":["つばさ","普段","しゅしょう"],"score":60}', NULL),
  ('rlwk5cxfd01kcrmsbxfa257k', '01958e26-385b-7060-a72c-3702ac2a57f3', 'ぎせい とふ えんちょうする 基盤 きょうふ きげんご. ちらかす れいせい こくふくする 病床 漂う ふゆかい 雰囲気 たいりく ざぜん. たまご ほうせき 陳列室 切迫 てのこう じぶん そうだん.', '563.10', '{"note":"はちまき ひかくする 新婚旅行 左手.","tags":["母","手作り"],"score":57}', NULL),
  ('ggw8771pjxq5ugg4nb1kgxo5', '019833e0-a257-756f-b074-375e5ce053e3', NULL, '1272.22', NULL, X'3e27cd9a83fda6b10e94bbe29863dac6'),
  ('kicjv7ctqcbdaavk3z9bz4x0', '0199c006-362d-75e7-96e1-a42ebd6c6da2', '消す むぜい いっさくじつ 耐火 むちつじょ ごらく. 送る おとろえる ねんがじょう いっこ こうちょく. 指定する 汚す 縛る 悔しい おおちがい 残業 学院 たれる.', '3447.23', '{"note":"間隔 こうちょく さと 無糖.","tags":["せんたくする","おおごえ"],"score":11}', X'50b793486b590bddf18af10a9357b5bc'),
  ('wkkoajv97ouvxfvb2gmelvz2', '019b1de0-2087-73f5-bcde-4193efd91934', '汚す 休日 山葵 希望する かつ. 割り箸 となえる かいぞく 日刊 いままで ぜんにほん あしくび そあく. さいばん なんべい ぎせい ねばり 主観的 下さい 解説.', '3394.55', '{"note":"はなはだ ねばり となえる 地面.","tags":["おんとう","沖縄","ようい"],"score":68}', NULL),
  ('z8o065a5ini56xg4asxgd1ie', '019a098c-d17d-706b-89b4-8897f0fe3d02', NULL, '3887.28', NULL, X'eb6effe00daa46d8f3befbab1124fbfd'),
  ('rvs1wv392zf7kqhm25ntfucy', '0199c6c0-cb6c-74e0-aeba-67a111ab41d4', NULL, '3887.29', '{"note":"かんしん ごうけん 飽くまでも 超〜 とふ 豪華.","tags":["仰々しい","じぎする"],"score":83}', X'4dc2d5ceafca4ca29b98acac656dd7cb'),
  ('h1h7lm7gt3eemjrbr0yxzf7z', '019a1def-2258-717e-95d9-c6afd1a13dc9', '疎外 運ぶ ちらかす こづつみ 満潮 間接 にる 火 なぞ. じぎする 春休み 高値 差し上げる 総括 ちらかす 所 写す. 味噌 太る おりめ 通す やぶれる 請ける 逆 おとこのこ 切迫.', '4551.74', '{"note":"いしゃりょう 柱 おんとう れいせい 移譲 しめる 聴者 七つ 歌謡 へいせい.","tags":["掛ける","ぎじゅく"],"score":83}', X'25dcefddfc360de024b84855ce5c0f2c');
