INSERT INTO `comments` (`id`, `body`, `post_id`, `author_id`) VALUES
  (1, '伐採 つうやく 一人娘 くまもとけん. 部首 むらさきいろ 無糖 むれる 普及 ついたち まもる しめらせる. 哀れむ むく はなのあな てのこう きづく 比較 じきしょうそう 話.', 39, NULL),
  (2, 'ばい 復旧 超音波 よすみ 乾燥 近視 りゃくず. へいがい ねんじ げんめつ じどうし 間接. 鶴 じぎする うごき.', 5, '0194ccb5-e684-7178-8878-dbf07801ff0c'),
  (3, '鶴 ふくせん 絹糸 零す つくる ちあん あい. 着く 仕方がない せいぞう うみ まつ 子守歌 破産. 魅力 面倒臭い たび ふくへい 左右 喜劇 せいしん まつ いち.', 11, '019b1e9e-492e-74ad-b135-d23edfb2db73'),
  (4, '高瀬 すんか 悲しみ よくあつ 近視. こわす すいせん ぶそう 社員. 送る 暗い 廃棄.', 20, NULL),
  (5, 'まぎらす けいけんしゃ まもる 専門 ほどう なさけない こうぎょう ひんしつ 縛る 約. 副大統領 鶴 きずつく みさき ちんもく 移譲 じぶん 溶岩 せいじょう ふそく. りゃくご 見当たる しずむ せいかん 繁茂 揺さぶる しどう のぞいて 終点.', 58, '0196268a-b3f5-768e-a053-1b221c4b63e9'),
  (6, '大尉 待遇 難しい あわ. たて そだてる 避ける 誓い 没頭 桜色 しざい やしなう いち かんどうする. こころみる 失う 悔しい こうとう 浸す.', 10, '01969fb5-5314-77e9-80bb-3368923fe2b2'),
  (7, 'ぶそう 毎日 舞踏 揺さぶる. 報じる 沖縄 おんとう しっぺい. ひふ 陳列室 かざる 警官 まんえつ.', 60, '0194ccb5-e684-7178-8878-dbf07801ff0c'),
  (8, 'しょうゆ 仕方がない りゅうき 帳簿 頑張れ 割り箸 まんえつ むれる 原油. 力 はんだんする 雰囲気 忘れ物 試験 せんじょうざい 陳列室 無糖. 迷子 すいがら 帳簿 きぼうする たおす 老齢 貴賓 非難 嫌.', 18, NULL),
  (9, '遺失 品詞 あっとうする よわよわしい ほんそう 逆 せいじょう. かんじる 待遇 継承 近視 こうばん 写す しゅいん ながさき 出かける. 何千 原油 いちにち たいこうする 十台.', 46, '01958e26-385b-7060-a72c-3702ac2a57f3'),
  (10, 'ごうけん よぼう 火 陳列室 おおごえ ひかくする 大間違い 普及 品詞 寮生. 封筒 りゃくご おきゃくさん 賢明 りゃくず たつ ほにゅうびん みき. とうとい おくれる しっぺい かぶしきしじょう 妥協する 縛る 委員 いたずら いちだい.', 48, '019b1e9e-492e-74ad-b135-d23edfb2db73'),
  (11, 'あびる かせぎ 貫く しばふ 閉める 可愛い 素材. いか 哀れむ ちゅうとはんぱ なつかしい ごうけん. 洋服 すみ 胃.', 59, NULL),
  (12, 'きょうかい 先週 副大統領 そうだん ほにゅうびん ふかさ 哀れむ 警官 がぞう. 凝固 始まる どうめい 電源 安泰 色々 〜亭. かつ ねんがん じょうだん まもる よすみ とうさく 閉じる.', 44, '019b1e9e-492e-74ad-b135-d23edfb2db73'),
  (13, 'あい 妥協する 都合 当て字 あらそう ひんきゃく つうやく かぶしきしじょう 好き. つなひき 運命 ふゆかい やしなう あらそう. ちかく ふゆかい 瞬く 零す 色彩 縮小 おおちがい.', 27, NULL),
  (14, 'ねばる ちんみ 〜系 模型 ふくぶくろ 解説 高瀬 かいそく 飽くまでも 始まる. ねばる 燃やす 魅力 浮世絵 扇 しょうりゃく 公共 継承 枕 ざせき. かんかつ 配慮 はきだす なんべい みずいろ.', 43, '019a1def-2258-717e-95d9-c6afd1a13dc9'),
  (15, 'ちきゅう 宜しく 当て字 電源. せっとく ひんきゃく 化粧 図説 しょひょう 以下 暗い だいがくいんせい かつぐ れつあく. 始まる 駆け出す 料理人 無駄 桑原.', 15, NULL),
  (16, '慶弔 つなひき 頂く 人性. 雰囲気 とくに はい. 高瀬 ごふく 日欧 暇 施設 近視.', 34, NULL),
  (17, 'さんぎょう じどうし のむ. える 仕方がない 渦巻き ひんきゃく ちゅうとはんぱ たまご ふくせん 洋服 電話 入江. ぞうえん にゅうせき じっかん おうしゅう うえる すんか.', 29, '0199c6c0-cb6c-74e0-aeba-67a111ab41d4'),
  (18, 'ぜんにほん 渦巻き 所. とう 比較 模型. 普段 競艇 あわれ 高瀬 すみ 会議 春休み かせぎ こわす.', 45, '0196ceee-f087-7321-90a4-1419f5e43440'),
  (19, '浅い 数える 隆起 対応. 既に 鋭い きょだい きげんご 歯 しきもう 黒板 普及. 溶岩 はなはだ 輪郭 きひん 二巻 学者 退く しょうげき.', 28, '019a1def-2258-717e-95d9-c6afd1a13dc9'),
  (20, '以下 おおごえ 殻 しゅいん 二つ ふくへい あらあらしい しょうじょう ひんきゃく. 壁 むぜい 匿名 耐火 ぶそう めいし 譜面 ぜんにほん たらす. 夏 氏名 半額 ぶそう お盆 じょうきゅう.', 38, '019a1def-2258-717e-95d9-c6afd1a13dc9'),
  (21, 'しえんする いしゃりょう 桑原. いっぱく 明治 廉価 当て字 主観的 香り わかめ. たいがい 漬物 順序 なげすてる こい.', 13, '0194ccb5-e684-7178-8878-dbf07801ff0c'),
  (22, '乙 禅寺 じしん ねんがじょう ゆるむ 自宅 せんりゅう 走り回る はなのあな. きひん あわれ 悪気 おんとう いちだい きじゅつ ししょく ちょう ししょく. ふさい 好奇心 きじゅつ.', 52, NULL),
  (23, '魅力 右利き さくにゅう 図説. たくす 忘れ物 華道 平安 こくふくする 悪気 九日 床. かいそく きぼうする ひかくする 燃やす ほうげん.', 19, '019833e0-a257-756f-b074-375e5ce053e3'),
  (24, 'いたずら おろし とふ 碁 媒介 好奇心. ほんそう 哺育 提案する. 面積 輸出 はきだす こくふくする 杏.', 29, '0199c6c0-cb6c-74e0-aeba-67a111ab41d4'),
  (25, 'かわかす むれる 好き. 歯を磨く おかね ちょくせつ 特殊. こうばん 溶岩 老齢 礎 うち むぼう 堀川.', 60, '01958e26-385b-7060-a72c-3702ac2a57f3'),
  (26, '和尚 特殊 面積 色々 貨物船 かんせつ めいしょ 運. 無駄 床 くら たらす 香り 風船. 遺失 みつ しききん いままで 哺育 つぎつぎ やすい とりあえず.', 31, NULL),
  (27, 'てら しばふ いっかい ふねんゴミ ほうき はっぽう 学院 あっとうする せんじょうざい みなと. じょうだん 教える 親子丼 江戸. 毎日 じゅうらい 豪華 ぼくし いか きづく.', 19, '019a098c-d17d-706b-89b4-8897f0fe3d02'),
  (28, '買い物 公共 やしなう ちがい めいわくめーる. 一生 誤用 うえる ねばり はちまき ねんじ. 待合 なんべい ぎじゅく そうぐう 主に 鶴 ついたち じしん 弥生 かいほうする.', 28, NULL),
  (29, '検査 嫌 たいがい とうひょうする 締まる りゃくご 黒板 せいぞう ねんがん. 泳ぐ 漠然 はなのあな がくふ 弥生 さわやか しざい みさき フランス人 締まる. かちゅう こうちょく 糸 陳列室 雑費 あい.', 30, '0194ae34-8559-7124-91fe-b5611049e836'),
  (30, '反則 悪気 一生 ちがい 移譲. しゃっか ほ 競艇 同僚 人口 いし めいわくメール はいき 胃 めいよ. おどりば 錠 せいしん.', 31, '0199c006-362d-75e7-96e1-a42ebd6c6da2'),
  (31, 'ほんらい 望み 象牙 さと 碁. かんぜん 一生 じゅうらい 限る たれる 原油 かわさき きゅうりょう 何千. すみ ざせき 希望する 報じる ふじ山.', 11, '0194ae34-8559-7124-91fe-b5611049e836'),
  (32, '話 もちいる 提案する 月刊 せんじょう 知り合い のぞいて 請ける たまご. まほうつかい こくふくする 歌謡 はいき ふかぶん 憂い. 輪郭 左手 えんちょうする ちょう.', 37, '019a098c-d17d-706b-89b4-8897f0fe3d02'),
  (33, 'かいじゅう きづく せんじょう 料理人 主観的 げんめつ かぜ 雰囲気 かど よそく. じょうだん 封筒 にゅうせき 縮小 どうけつ 川底. 丼 老齢 はきだす 洋服 がいよう 泳ぐ 金.', 24, '01969fb5-5314-77e9-80bb-3368923fe2b2'),
  (34, '日欧 基盤 そんざい あつかい 競艇 着く うち 天井. こうおつ いっぱく 瞬く みぎて くら かっこう. れいてん となえる みさき 零す 運命 薬 色々 つぎ そうぐう.', 16, NULL),
  (35, '皇太子妃 恥ずかしがる 待合 部首 非難 なつかしい 馬. 胃 胃 歯. ぶそう げんまい 濃紺 ふそく.', 43, NULL),
  (36, '空き瓶 洗剤 となえる りょうど 封筒 気持ちいい. 病床 さくにゅう 好き 限る 何度. ふさい 七つ おなか しんぞう フランス人 こわす.', 18, '019b1de0-2087-73f5-bcde-4193efd91934'),
  (37, '体重 主観的 りょこう ひんきゃく あおい 手作り もちいる. つみ 哺育 無糖 貨幣 帝 かいぞく. 縮小 杏 めいよ ぶそう 屈む とうさん 何度 はんそう.', 20, '0199c6c0-cb6c-74e0-aeba-67a111ab41d4'),
  (38, 'ふくし ぼきん ちあん 不況 壊す 飽くまでも 燃やす 公共 けんしゅうせい おんとう. ようい 暇 〜亭 俵 てのこう おとこのこ かけこむ 柱. 迷路 浮世絵 ために 胃腸.', 5, '01958e26-385b-7060-a72c-3702ac2a57f3'),
  (39, 'せいじょう 継承 知り合い じょうだん. いっかい 廃棄 頑張れ 子守歌 けむし たれる. 迷路 かぶしきしじょう ぶん やしなう おとろえる 没落 こわす.', 16, '01954ca3-013f-7258-a999-6d4601784673'),
  (40, '乾燥 よぼう 無敵 ざんぴん むく 機嫌 つくる. 謙虚 歯 濃紺 〜亭 へいがい おおごえ あまい 仰々しい 宝くじ. 廃棄 金 ほうしゅう かくしゅう れいぞうこ ぜんにほん かんさい げんめつ.', 5, '019661e5-75cc-74c2-a9a9-cacb8575c7e3'),
  (41, '生える ぐん いっかい 重い よそく. 救急車 とりあえず 無糖 すみ おくれる 帳簿 せんりゅう たらす. 分ける 不可欠 ちょう 墨.', 58, '01954ca3-013f-7258-a999-6d4601784673'),
  (42, '無敵 割り箸 かわかす ちゅうもんする. 延長 壊す とう 破産 果てる どうけつ 歌謡 ほうき 愛する. おりめ 雇用 あらあらしい あつい なぞ 望み いう めいよ 軒 ししょく.', 8, '01969fb5-5314-77e9-80bb-3368923fe2b2'),
  (43, '左手 曲 機嫌 指定する 間接. きづく あつかい ようい 魔術 かんさい. むこう 恨み 超音波 おうしゅう せいじょう 特殊 ずいぶん きょうふ れいせい.', 32, '019a098c-d17d-706b-89b4-8897f0fe3d02'),
  (44, '指定する 歯を磨く 終点 閉める 曲 縮小 ごらく 退く くまもとけん 勇気. 対応 話 ふねんゴミ. 仕事 ちんみ 忘れ物 開閉 人口 問題 非難.', 43, '0199c6c0-cb6c-74e0-aeba-67a111ab41d4'),
  (45, '底 匿名 曲 じょうきゅう ちんみ こたえる かんそく アメリカ製. こうせい なげすてる 初めに 長唄. 金星 はんそう じぶん にゅうせき.', 23, '01969fb5-5314-77e9-80bb-3368923fe2b2'),
  (46, 'きょだい せんりゅう ぶっきょう 忘れ物 面. ちんみ 当て字 遺失 歌謡. 境 きょだい はきだす.', 38, '0199c006-362d-75e7-96e1-a42ebd6c6da2'),
  (47, 'ふたたび ちめいてき そあく すんか. だいがくいんせい きひん 俵 店. へいせい むぜい ハチのす いか たつ 安泰.', 44, '0194ccb5-e684-7178-8878-dbf07801ff0c'),
  (48, 'しあとるし 魅力 かせぎ 妥協する 切迫 ししょく 化粧 ないしょばなし 解説. しゃくや 渦巻き 副大統領 急騰 勇気 締まる 主観的 壮年. ひきざん 急騰 むれる 乙.', 31, NULL),
